skills.card:
lexiconSentiment — Judge whether text sounds happy or unhappy, positive or negative.
  needs: text: string
  e.g. "how positive is this review" → {"text":"This is an excellent product and I really love it"}

readingLevel — Estimate the reading age of a passage — reading ease and school grade level.
  needs: text: string
  e.g. "how hard is this to read" → {"text":"The cat sat on the mat. It was a warm day."}

stemWords — Reduce words to their stems so different forms of the same word group together.
  needs: text: string
  e.g. "stem running runs and runner" → {"text":"running runs runner"}

syllableCount — Count the syllables — the beats — in a word or a text.
  needs: text: string
  e.g. "how many syllables in beautiful" → {"text":"beautiful"}

tokenizeSentences — Break a passage at its full stops into separate sentences.
  needs: text: string
  e.g. "split this into sentences" → {"text":"Hello there. How are you? I am well."}

